def classify_rects(grid):
    rows, cols = len(grid), len(grid[0])

    # Get bounding box of connected components of each color
    components = {}  # color -> [(r,c) for each connected component]

    for color in [1, 2, 4, 5, 8, 9]:
        visited = set()
        components[color] = []

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color and (r,c) not in visited:
                    # Flood fill
                    comp = []
                    stack = [(r,c)]
                    while stack:
                        sr, sc = stack.pop()
                        if (sr, sc) in visited:
                            continue
                        visited.add((sr, sc))
                        comp.append((sr, sc))

                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = sr+dr, sc+dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if grid[nr][nc] == color and (nr,nc) not in visited:
                                    stack.append((nr, nc))
                    components[color].append(comp)

    return components

